import{disassembleScript}from'./script-engine.js';
export function auditReconstructionScripts(reader,map){
 const native=reader.byKey(map.rom?.key);if(!native||reader.engine!==map.rom.engine)return{complete:false,cells:[],reason:'The matching native map is unavailable.'};
 const roots=new Set(),events=reader.events(native),cells=new Set();let complete=true,reason='';for(const n of [...events.npcs,...events.triggers,...events.signs.filter(n=>n.type<5)])if(n.script>=512)roots.add(n.script);
 let at=native.scripts;for(let i=0;at>=512&&reader.valid(at,5)&&reader.u8(at)&&i<32;i++,at+=5){const type=reader.u8(at),p=reader.ptr(at+1);if([1,3,5,6,7].includes(type))roots.add(p);else if([2,4].includes(type)){for(let j=0;j<64;j++){const q=p+j*8;if(!reader.valid(q,8)){complete=false;break;}if(!reader.u16(q))break;roots.add(reader.ptr(q+4));if(j===63)complete=false;}}else complete=false;if(i===31)complete=false;}
 for(const root of roots)try{const decoded=disassembleScript(reader.bytes,root,reader.engine,true);for(const line of decoded.source.split('\n')){const m=/^(setmetatile|setmaptile)\s+(\S+)\s+(\S+)/.exec(line);if(m){const[x,y]=m.slice(2).map(v=>Number(v.replaceAll(',','')));if(!Number.isInteger(x)||!Number.isInteger(y)||x>=0x4000||y>=0x4000){complete=false;reason='A script changes tiles using dynamic coordinates.';}else{const dx=x-(map.rom.cropOffset?.x||0),dy=y-(map.rom.cropOffset?.y||0);if(dx>=0&&dy>=0&&dx<map.width&&dy<map.height)cells.add(dy*map.width+dx);}}if(/^(setmaplayoutindex|setmaplayout|callnative)\b/.test(line)){complete=false;reason='A native routine or layout change needs manual review.';}}}catch{complete=false;reason='Some native event commands could not be decoded.';}
 return{complete,cells:[...cells],reason:reason||(!complete?'The map script table needs manual review.':'')};
}
